NEW_GUARD_SHA='8ae864591b9da930c49961a14849ce9295bc81c5f30aa4ae950fee633e26019a'

ROOT=Path(__file__).resolve().parents[2]
sha=lambda b:hashlib.sha256(b).hexdigest()
def freeze(root,out):
    for n,h in FROZEN.items():
        p=out/'frozen'/n
        if not p.exists():
            data=(root/n).read_bytes();assert sha(data)==h,n;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
        assert sha(p.read_bytes())==h,n
        if n in UPDATED_TOOLS:assert sha((root/n).read_bytes())==UPDATED_TOOLS[n],n
        elif n not in {SOURCE,OBJECT,ELF,GUARDS,'conker/build/conker.us.bin'}:assert sha((root/n).read_bytes())==h,n
    assert sha((root/GUARDS).read_bytes())in(FROZEN[GUARDS],NEW_GUARD_SHA)
    return FROZEN
def source_states(live):
    old=(ROOT/BUILD/'frozen'/SOURCE).read_text();assert sha((ROOT/BUILD/'frozen'/SOURCE).read_bytes())==FROZEN[SOURCE]
    assert live in(old,NEW_SOURCE),'Unknown resource-resolver source';return old,NEW_SOURCE,live==NEW_SOURCE
def guards(out):
    old=(out/'frozen'/GUARDS).read_bytes();newline='\r\n'if b'\r\n'in old else'\n';stream=io.StringIO(newline='')
    writer=csv.DictWriter(stream,fieldnames=old.splitlines()[0].decode().split(','),lineterminator=newline);writer.writerows(GUARD_ROWS)
    result=old+stream.getvalue().encode();assert sha(result)==NEW_GUARD_SHA and result.startswith(old)
    return result
def strict_image(before,actual,truth):
    assert sha(before)==FROZEN[ELF]and len(truth)==SIZE and sha(truth)==RETAIL_SHA
    expected=bytearray(before);at=elf_slot_offset(before,ENTRY,SIZE);expected[at:at+SIZE]=truth
    rows=[(p,v)for p,n,v,_ in symbol_rows(before)if n==FUNCTION];assert len(rows)==1 and rows[0][1][1:3]==(ENTRY,620)
    struct.pack_into('>I',expected,rows[0][0]+8,SIZE)
    assert bytes(expected)==actual,'Whole image differs from body and extent prediction'
    return sum(a!=b for a,b in zip(before,actual))

def actual_make(proposal,guards,wanted,label):
 root=ROOT;out=root/BUILD
 base=Path(tempfile.mkdtemp(prefix='conker-resolver-Make-'));conker=base/'conker';conker.mkdir()
 for name in('tools','ido'):(base/name).symlink_to(root/name,target_is_directory=True)
 for name in('include','asm'):(conker/name).symlink_to(root/'conker'/name,target_is_directory=True)
 for name in('Makefile','retail_layout.us.txt'):(conker/name).write_bytes((root/'conker'/name).read_bytes())
 p=conker/'src/game/generated_139FC0.c';p.parent.mkdir(parents=True);p.write_bytes(proposal.read_bytes())
 (conker/'retail_word_patches.us.csv').write_bytes(guards.read_bytes())
 (conker/'build/src/game').mkdir(parents=True)
 command=['make','-B','-o','Makefile','build/src/game/generated_139FC0.c.o']
 r=subprocess.run(command,cwd=conker,capture_output=True,text=True);(out/(label+'-actual-Make.log')).write_text(r.stdout+r.stderr);assert r.returncode==0,(r.stdout+r.stderr)[-8000:]
 obj=conker/'build/src/game/generated_139FC0.c.o';assert obj.read_bytes()==wanted.read_bytes(),'Actual Make object differs'
 cc=[line for line in r.stdout.splitlines()if'-c -32'in line];assert len(cc)==1 and'-O2 -g3'in cc[0]
 report=dict(commands=3,byte_identical_Makefile=True,Makefile_sha256=hashlib.sha256((conker/'Makefile').read_bytes()).hexdigest(),guard_sha256=hashlib.sha256(guards.read_bytes()).hexdigest(),object_equal=True,workspace=str(base),command=command,compiler=cc[0])
 (out/(label+'-actual-Make.json')).write_text(json.dumps(report,indent=2)+'\n');return report

def prepare(root=ROOT):
    root=Path(root).resolve();out=root/BUILD;out.mkdir(parents=True,exist_ok=True);freeze(root,out)
    old,new,installed=source_states((root/SOURCE).read_text())
    assert ((root/GUARDS).read_bytes()==guards(out))==installed
    (out/'proposed-guards.csv').write_bytes(guards(out))
    (out/'final-owner.c').write_text(new)
    rom=(root/'conker/conker.us.bin').read_bytes();(out/'retail-slot.bin').write_bytes(rom[ROM:ROM+SIZE])
    assembly=(root/'conker/asm/139FC0.s').read_text();a=assembly.index('glabel '+FUNCTION+'\n');b=assembly.index('endlabel '+FUNCTION,a)+len('endlabel '+FUNCTION)
    p=out/'retail-reference.s';p.write_text('.include "macro.inc"\n.set noat\n.set noreorder\n.set gp=64\n.text\n'+assembly[a:b]+'\n.size '+FUNCTION+', .-'+FUNCTION+'\n')
    subprocess.run(['mips-linux-gnu-as','-EB','-mtune=vr4300','-march=vr4300','-mabi=32','-I',str(root/'conker/include'),'-o',str(out/'retail-reference.o'),str(p)],capture_output=True,check=True)
    before,od=compile_owner(root,out,old,'predecessor-owner');after,nd=compile_owner(root,out,new,'qualified-owner');assert not od and not nd
    assert same_functions(before,after,(FUNCTION,))==13 and normalized_pools(before)==normalized_pools(after)
    rom=(root/'conker/conker.us.bin').read_bytes();truth=rom[0x13A59C:0x13A824];assert len(truth)==648
    base=dict(FUNCTION=FUNCTION,OWNER='generated_139FC0',SOURCE=SOURCE,OBJECT=OBJECT,ASM='conker/asm/139FC0.s',ENTRY=ENTRY)
    with patch.multiple(shared,**base,GUARDS=str((out/'frozen/conker/retail_word_patches.us.csv').relative_to(root))):oldpad=shared.padded(root,out,before,'predecessor-padded',True)
    with patch.multiple(shared,**base,GUARDS=str((out/'proposed-guards.csv').relative_to(root))):
     raw,refs=shared.payload(after)
     newpad=shared.padded(root,out,after,'qualified-padded',True);independent=shared.padded(root,out,after,'independent-padded')
     assert same_functions(newpad,independent)==14 and same_functions(oldpad,newpad,(FUNCTION,))==13
     assert normalized_pools(oldpad)==normalized_pools(newpad)==normalized_pools(independent)
     assert (root/OBJECT).read_bytes()==(newpad if installed else oldpad).read_bytes()
     fixed,bindings=shared.payload(newpad);symbols={n:int(n.split('_')[1],16)for rows in bindings.values()for _,n in rows}
     assert len(raw)==len(fixed)==648 and struct.pack('>162I',*bound_blob(fixed,bindings,symbols))==truth
     reg_before=struct.unpack('>6I',sections(before)['.reginfo'][1]);reg_after=struct.unpack('>6I',sections(after)['.reginfo'][1])
     assert reg_before==reg_after,(reg_before,reg_after)
     recipe=actual_make(out/'final-owner.c',out/'proposed-guards.csv',newpad,'owner-Make')
    canonical=[]
    for name,p in(('old',oldpad),('new',newpad)):
     q=out/('canonical-'+name)/'generated_139FC0.c.o';q.parent.mkdir(exist_ok=True);q.write_bytes(p.read_bytes());canonical.append(q)
    with patch.multiple(shared.linker,FILENAME='generated_139FC0',OBJECT=OBJECT,LINKER='conker/build/conker.ld'):
     oldelf=shared.linker.link_image(root,out,canonical[0],'predecessor-image');newelf=shared.linker.link_image(root,out,canonical[1],'qualified-image')
    assert oldelf.read_bytes()==(out/'frozen'/ELF).read_bytes()
    a,_,aa=load_elf_functions(str(oldelf),'mips-linux-gnu-objdump');b,_,bb=load_elf_functions(str(newelf),'mips-linux-gnu-objdump')
    assert a.keys()==b.keys()and aa==bb and[n for n in b if a[n]!=b[n]]==[FUNCTION]
    assert b[FUNCTION]==list(struct.unpack('>162I',truth))
    expected=bytearray(oldelf.read_bytes());at=elf_slot_offset(expected,ENTRY,648);expected[at:at+648]=truth
    rows=[(p,v)for p,n,v,_ in symbol_rows(expected)if n==FUNCTION];assert len(rows)==1 and rows[0][1][2]==620
    struct.pack_into('>I',expected,rows[0][0]+8,648)
    actual=newelf.read_bytes();different=[i for i,(x,y)in enumerate(zip(expected,actual))if x!=y];assert len(expected)==len(actual)
    layout=audit_layout(newelf,root/'conker');assert layout['exact']and layout['different_bytes']==0
    report=dict(source_installed=installed,metadata_permuted_symbols=0,words=162,slot_words=162,padding_words=0,frame=80,guards=76,inherited_diagnostics=0,raw_neighbors=13,padded_neighbors=13,object_reginfo_before=reg_before,object_reginfo_after=reg_after,
     actual_Make=recipe,strict_unexplained_bytes=len(different),strict_first_offsets=different[:20],functions=len(a),all_addresses_fixed=True,
     protected_data=layout,raw_sha256=shared.sha(raw),refs=refs,ELF_sha256=shared.sha(actual),owner_sha256=shared.sha(newpad.read_bytes()),
     image_changed_bytes=sum(x!=y for x,y in zip(oldelf.read_bytes(),actual)))
    (out/'qualification.json').write_text(json.dumps(report,indent=2)+'\n')
    assert not different,'Strict image mismatch'
    assert (root/ELF).read_bytes()==(newelf if installed else oldelf).read_bytes()
    assert strict_image(oldelf.read_bytes(),actual,truth)==report['image_changed_bytes']==485
    return report
